def old(n,i,minutes=None,segment=None):
 t=OLD[n][i-1]['notes']
 if minutes is not None:t=re.sub(r'TIME: [\d.]+ minutes',f'TIME: {minutes:g} minutes',t)
 if segment:t=t.replace('\nDO\n','\nDO\nTHIS SLIDE: '+segment+'\n\nWhole source activity context:\n',1)
 return t

def n4(minutes,do,say='',key='',check=False,**kw):
 if check:
  kw.setdefault('look','Check the specified pupil work against the answer key. Include pupils with different predictions, not only volunteers.')
  kw.setdefault('iff','Ask the pupil to point to the diagram evidence, explain the function, then revise in a new colour. Reteach the identified structure if needed.')
 kw['science']=kw.get('science','')+'\nV2 Lesson 4 controls the activity. All science visuals are drawings, not electron micrographs. Source-owner and teacher approval, ARES and native PowerPoint checks remain open.'
 return note(minutes,do,say=say,key=key,**kw)

class Lesson:
 def __init__(self,n):self.n=n;self.b=VisualDeck(n,NAMES[n])
 def add(self,title,phase,i=None,mins=None,sub='',check=False,segment=None,**kw):
  notes=old(self.n,i,mins,segment) if i else n4(mins,kw.pop('do'),check=check,**kw)
  return self.b.slide(title,phase,notes,sub,check=check)
 def common(self,title,desc,hero,goals,words,phases,materials):
  n=self.n;b=self.b
  notes=old(n,1) if n!=4 else n4(.25,'Introduce the title without teaching organelle functions.',say=desc,purpose=DATA['LESSONS'][3]['slo']['purposeInStoryline'],before='Prepare blank plant outlines, labelled reference diagrams, the nine-row Job Card, green/red pens, notebooks and two note colours. Use the supplied diagram-only route. The optional maize chloroplast/onion vacuole/adjacent-wall electron micrographs in V2 are not supplied or authenticated; do not describe these drawings as EM evidence. Secure projector cables and avoid exposed staples. No wet practical. Have Version 1 models ready. Read the full source and logged science corrections.')
  s=b.slide('', 'Predict',notes,dark=True)
  tx(s,f'GRADE 10 BIOLOGY · CELL STRUCTURE · LESSON {n} OF 12',.7,.99,7.2,.4,13,'D7DF23',True)
  tx(s,title,.7,1.85,7.05,1.65,43,'FFFFFF',True);tx(s,desc,.73,3.72,6.7,1.05,24,'D2E4E8')
  photo(s,hero,8.25,1.12,4.35)
  for i,(ph,c) in enumerate(COL.items()):
   xx=.73+(i%3)*2.45;yy=5.28+(i//3)*.58
   oval(s,xx,yy+.04,.18,.18,c);tx(s,ph,xx+.3,yy,2.0,.48,13,'FFFFFF',True)
  tx(s,('40' if n in [1,3,11] else '80')+' MINUTES · REVIEW DRAFT · 24 OCT 2026',.73,6.53,8,.25,11,'FCBA63',True)
  notes=old(n,2) if n!=4 else n4(0,'Read the orientation before teaching. Slides 2–3 remain hidden. Use Presenter View for notes.')
  s=b.slide('One routine. Five phases.','Routine',notes,hidden=True)
  for i,(ph,c) in enumerate(COL.items()):
   box(s,.7,2.15+i*.72,2.8,.52,c);tx(s,ph,.82,2.26+i*.72,2.56,.3,15,INK,True)
   tx(s,['Commit to your own idea before teaching.','Record what you see, read or measure.','Use evidence to explain and revise.','Track growing understanding and questions.','Revise the same model in a new colour.'][i],3.8,2.23+i*.72,8.7,.45,21)
