  tx(s,'A check label points to LOOK FOR and IF… guidance in the notes.',.75,6.55,11.8,.3,14,MUTED)
  notes=old(n,3) if n!=4 else n4(0,'Prepare all materials listed. Per pupil: notebook, pencil, blank plant outline, Job Card, green/red pens, one note. Shared: large plant diagram, board/timer, projector or printed diagrams. No wet materials. If printing is short, learners copy the outline and table from the board.',science='Optional real EM images are not embedded. The core diagram-only route is permitted by the source. Each ARES resource is Preview first, not an established exact match; preview for accuracy and spoilers. No resource should precede Predict.\n'+resources_audit(4))
  s=b.slide(f'Lesson {n} at a glance','Glance',notes,hidden=True)
  table(s,['Phase','min','What pupils do'],phases,.7,2.05,8.2,4.45,[2.3,.65,5.25],14)
  tx(s,'PREPARE',9.2,2.1,3.4,.3,13,INK,True);tx(s,materials,9.2,2.62,3.35,2.5,16)
  for i,item in enumerate(resources(n)[:3]):
   sh=box(s,9.15,5.25+i*.43,3.5,.36,INK);sh.click_action.hyperlink.address=item['direct_url'];sh=tx(s,item['title']+' · see audit',9.25,5.31+i*.43,3.3,.24,10,'FFFFFF');sh.click_action.hyperlink.address=item['direct_url']
  tx(s,'Resource audit + fallback: see notes.',9.15,6.63,3.6,.2,10,MUTED)
  notes=old(n,4) if n!=4 else n4(.5,'Point to Lesson 4. Recall the generalised model from L2–3.',say='Today we examine how the parts of a photosynthetic plant cell work together.')
  s=b.slide('Where are we in the investigation?','Unit map',notes)
  for i,t in enumerate(TITLES):
   xx=.7+(i//6)*6.1;yy=2.15+(i%6)*.48;c='D7DF23' if i==n-1 else 'F0F4F4'
   box(s,xx,yy,5.85,.4,c);badge(s,str(i+1),xx+.07,yy+.035,INK if i!=n-1 else 'FFFFFF',.32);tx(s,t,xx+.55,yy+.07,3.85 if i==n-1 else 4.95,.28,15,INK,i==n-1)
